<?php
require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/../public/db_connect.php';
require_login();  $u = current_user();
$role = role_key($u['role'] ?? 'staff');
$station_id = user_station_id();  // Only managers can access this page
if ($role !== 'manager') {  header('Location: dashboard.php');  exit;
}  // Get completed jobs pending review
$pending_review = [];
try {  $stmt = $pdo->prepare("  SELECT jo.*,  COALESCE(c.customer_name, jo.customer_name, 'Walk-in') as customer_name,  t.full_name as technician_name,  sc.name as service_name,  sc.fixed_labor_rate,  sc.estimated_time_minutes,  COALESCE(NULLIF(CONCAT(u.first_name,' ',u.last_name),' '), u.username) as created_by_name,  TIMESTAMPDIFF(MINUTE, jo.started_at, jo.completed_at) as actual_duration_minutes  FROM job_orders jo  LEFT JOIN customers c ON c.id = jo.customer_id  LEFT JOIN technicians t ON t.id = jo.assigned_technician_id  LEFT JOIN mechanics m ON m.id = jo.assigned_mechanic_id  LEFT JOIN service_categories sc ON sc.id = jo.service_category_id  LEFT JOIN users u ON u.id = jo.assigned_by  WHERE jo.station_id = ?  AND jo.status = 'Completed'  AND jo.reviewed_by IS NULL  ORDER BY jo.completed_at DESC  ");  $stmt->execute([$station_id]);  $pending_review = $stmt->fetchAll(PDO::FETCH_ASSOC);
} catch (Exception $e) {  $pending_review = [];
}  // Get recently reviewed jobs
$recently_reviewed = [];
try {  $stmt = $pdo->prepare("  SELECT jo.*,  COALESCE(c.customer_name, jo.customer_name, 'Walk-in') as customer_name,  t.full_name as technician_name,  sc.name as service_name,  sc.fixed_labor_rate,  COALESCE(NULLIF(CONCAT(reviewer.first_name,' ',reviewer.last_name),' '), reviewer.username) as reviewed_by_name,  jo.reviewed_at  FROM job_orders jo  LEFT JOIN customers c ON c.id = jo.customer_id  LEFT JOIN technicians t ON t.id = jo.assigned_technician_id  LEFT JOIN mechanics m ON m.id = jo.assigned_mechanic_id  LEFT JOIN service_categories sc ON sc.id = jo.service_category_id  LEFT JOIN users reviewer ON reviewer.id = jo.reviewed_by  WHERE jo.station_id = ?  AND jo.status = 'Completed'  AND jo.reviewed_by IS NOT NULL  AND DATE(jo.reviewed_at) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)  ORDER BY jo.reviewed_at DESC  LIMIT 20  ");  $stmt->execute([$station_id]);  $recently_reviewed = $stmt->fetchAll(PDO::FETCH_ASSOC);
} catch (Exception $e) {  $recently_reviewed = [];
}  include __DIR__ . '/../partials/header.php';
