</style>  <div class="manager-review">  <div class="page-header">  <div>  <h1 class="page-title">Job Review Dashboard</h1>  <p style="color: var(--muted); margin-top: 5px;">Review completed jobs and approve final billing</p>  </div>  </div>  <div class="stats-grid">  <div class="stat-card">  <div class="stat-number"><?php echo count($pending_review); ?></div>  <div class="stat-label">Pending Review</div>  </div>  <div class="stat-card">  <div class="stat-number"><?php echo count($recently_reviewed); ?></div>  <div class="stat-label">Reviewed This Week</div>  </div>  <div class="stat-card">  <div class="stat-number">  <?php  $total_value = array_sum(array_merge(  array_column($pending_review, 'fixed_labor_rate'),  array_column($recently_reviewed, 'fixed_labor_rate')  ));  echo '₱' . number_format($total_value, 2);  ?>  </div>  <div class="stat-label">Total Labor Value</div>  </div>  </div>  <div class="review-section">  <h3 class="section-title">  Pending Review  <?php if (count($pending_review) > 0): ?>  <span style="background: #DC3545; color: white; padding: 2px 8px; border-radius: 12px; font-size: 12px;">  <?php echo count($pending_review); ?> jobs  </span>  <?php endif; ?>  </h3>  <?php if (empty($pending_review)): ?>  <div class="empty-state">  <div class="empty-state-icon"></div>  <div class="empty-state-title">All caught up!</div>  <div class="empty-state-text">No jobs pending review at the moment.</div>  </div>  <?php else: ?>  <?php foreach ($pending_review as $job): ?>  <div class="job-card">  <div class="job-header">  <div>  <div class="job-title"><?php echo htmlspecialchars($job['job_order_number']); ?></div>  <div class="job-meta">  Customer: <?php echo htmlspecialchars($job['customer_name'] ?? 'Walk-in'); ?>  Technician: <?php echo htmlspecialchars($job['technician_name'] ?? 'Not assigned'); ?>  Completed: <?php echo date('M j, Y H:i', strtotime($job['completed_at'])); ?>  </div>  </div>  <span class="status-badge status-completed">Completed</span>  </div>  <div class="job-details">  <div class="job-detail">  <span class="job-detail-label">Service:</span>  <?php echo htmlspecialchars($job['service_name']); ?>  </div>  <div class="job-detail">  <span class="job-detail-label">Fixed Labor Rate:</span>  ₱<?php echo number_format($job['fixed_labor_rate'] ?? 0, 2); ?>  </div>  <div class="job-detail">  <span class="job-detail-label">Est. Time:</span>  <?php echo $job['estimated_time_minutes'] ?? 60; ?> mins  </div>  <div class="job-detail">  <span class="job-detail-label">Actual Time:</span>  <?php echo $job['actual_duration_minutes'] ?? 'N/A'; ?> mins  </div>  </div>  <div class="job-actions">  <button class="btn btn-primary" onclick="reviewJob(<?php echo $job['id']; ?>)">  ️ Review & Approve  </button>  <button class="btn btn-secondary" onclick="viewJobDetails(<?php echo $job['id']; ?>)">  View Details  </button>  </div>  </div>  <?php endforeach; ?>  <?php endif; ?>  </div>  <div class="review-section">  <h3 class="section-title">  Recently Reviewed  </h3>  <?php if (empty($recently_reviewed)): ?>  <div class="empty-state">  <div class="empty-state-icon"></div>  <div class="empty-state-title">No recent reviews</div>  <div class="empty-state-text">Jobs reviewed in the last 7 days will appear here.</div>  </div>  <?php else: ?>  <?php foreach ($recently_reviewed as $job): ?>  <div class="job-card">  <div class="job-header">  <div>  <div class="job-title"><?php echo htmlspecialchars($job['job_order_number']); ?></div>  <div class="job-meta">  Customer: <?php echo htmlspecialchars($job['customer_name'] ?? 'Walk-in'); ?>  Reviewed by: <?php echo htmlspecialchars($job['reviewed_by_name']); ?>  </div>  </div>  <span class="status-badge status-reviewed">Reviewed</span>  </div>  <div class="job-details">  <div class="job-detail">  <span class="job-detail-label">Service:</span>  <?php echo htmlspecialchars($job['service_name']); ?>  </div>  <div class="job-detail">  <span class="job-detail-label">Fixed Labor Rate:</span>  ₱<?php echo number_format($job['fixed_labor_rate'] ?? 0, 2); ?>  </div>  <div class="job-detail">  <span class="job-detail-label">Reviewed:</span>  <?php echo date('M j, Y H:i', strtotime($job['reviewed_at'])); ?>  </div>  </div>  </div>  <?php endforeach; ?>  <?php endif; ?>  </div>
</div>  <!-- Job Review Modal -->
<div id="reviewModal" class="modal">  <div class="modal-content">  <div class="modal-header">  <h3 class="modal-title">Review Job Order</h3>  <button class="modal-close" onclick="closeModal('reviewModal')">&times;</button>  </div>  <div class="modal-body" id="reviewModalBody">  <!-- Content will be loaded dynamically -->  </div>  <div class="modal-footer">  <button type="button" class="btn btn-danger" onclick="rejectJob()">Reject</button>  <button type="button" class="btn btn-success" onclick="approveJob()">Approve</button>  </div>  </div>
</div>  <script>
let currentJobId = null;
let currentJobData = null;  function reviewJob(jobId) {  currentJobId = jobId;  // Fetch job details with parts  fetch(`job_order_operations.php`, {  method: 'POST',  headers: {'Content-Type': 'application/x-www-form-urlencoded'},  body: `action=get_job_details&job_id=${jobId}`  })  .then(response => response.json())  .then(data => {  if (data.success) {  currentJobData = data.data;  displayJobReview(data.data);  document.getElementById('reviewModal').style.display = 'block';  } else {  alert('Error loading job details: ' + data.message);  }  });
}  function displayJobReview(job) {  const modalBody = document.getElementById('reviewModalBody');  // Calculate totals  const laborCost = parseFloat(job.fixed_labor_rate || 0);  const partsCost = parseFloat(job.total_parts_cost || 0);  const subtotal = laborCost + partsCost;  const tax = subtotal * 0.12;  const total = subtotal + tax;  modalBody.innerHTML = `  <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px;">  <div>  <h4>Job Information</h4>  <div style="background: var(--bg); padding: 15px; border-radius: 6px; margin-bottom: 15px;">  <div><strong>Job Order:</strong> ${job.job_order_number}</div>  <div><strong>Customer:</strong> ${job.customer_name || 'Walk-in'}</div>  <div><strong>Technician:</strong> ${job.technician_name || 'Not assigned'}</div>  <div><strong>Service:</strong> ${job.service_name}</div>  <div><strong>Completed:</strong> ${new Date(job.completed_at).toLocaleString()}</div>  </div>  <h4>Work Notes</h4>  <div style="background: var(--bg); padding: 15px; border-radius: 6px;">  ${job.notes || '<em>No work notes provided</em>'}  </div>  </div>  <div>  <h4>Cost Breakdown</h4>  <div class="cost-breakdown">  <div class="cost-row">  <span class="cost-label">Labor (Fixed Rate):</span>  <span class="cost-value">₱${laborCost.toFixed(2)}</span>  </div>  <div class="cost-row">  <span class="cost-label">Parts Used:</span>  <span class="cost-value">₱${partsCost.toFixed(2)}</span>  </div>  <div class="cost-row">  <span class="cost-label">Subtotal:</span>  <span class="cost-value">₱${subtotal.toFixed(2)}</span>  </div>  <div class="cost-row">  <span class="cost-label">Tax (12%):</span>  <span class="cost-value">₱${tax.toFixed(2)}</span>  </div>  <div class="cost-row">  <span class="cost-label">Total Amount:</span>  <span class="cost-value">₱${total.toFixed(2)}</span>  </div>  </div>  <div class="alert alert-info">  <strong>Fixed Rate Labor:</strong> Labor cost is fixed at ₱${laborCost.toFixed(2)} regardless of actual time spent.  </div>  </div>  </div>  ${job.parts_used && job.parts_used.length > 0 ? `  <h4 style="margin-top: 20px;">Parts Used</h4>  <table class="parts-table">  <thead>  <tr>  <th>Part Name</th>  <th>Quantity</th>  <th>Unit Cost</th>  <th>Total Cost</th>  </tr>  </thead>  <tbody>  ${job.parts_used.map(part => `  <tr>  <td>${part.product_name || part.part_name || 'Unknown'}</td>  <td>${part.quantity_used}</td>  <td>₱${parseFloat(part.unit_cost).toFixed(2)}</td>  <td>₱${parseFloat(part.total_cost).toFixed(2)}</td>  </tr>  `).join('')}  </tbody>  </table>  ` : '<div class="alert alert-warning">No parts were recorded for this job.</div>'}  <div class="form-group">  <label class="form-label">Review Notes</label>  <textarea class="form-textarea" id="reviewNotes" placeholder="Add any notes about this review..."></textarea>  </div>  `;
}  function approveJob() {  if (!confirm('Approve this job order? This will finalize the billing and make it ready for payment processing.')) {  return;  }  const notes = document.getElementById('reviewNotes').value;  fetch('job_order_operations.php', {  method: 'POST',  headers: {'Content-Type': 'application/x-www-form-urlencoded'},  body: `action=update_job_status&job_id=${currentJobId}&new_status=Reviewed&notes=${encodeURIComponent(notes)}`  })  .then(response => response.json())  .then(data => {  if (data.success) {  alert('Job order approved successfully!');  closeModal('reviewModal');  location.reload();  } else {  alert('Error: ' + data.message);  }  });
}  function rejectJob() {  const reason = prompt('Please provide a reason for rejection:');  if (!reason) {  return;  }  const notes = document.getElementById('reviewNotes').value;  const fullNotes = `REJECTED: ${reason}\n${notes}`;  fetch('job_order_operations.php', {  method: 'POST',  headers: {'Content-Type': 'application/x-www-form-urlencoded'},  body: `action=update_job_status&job_id=${currentJobId}&new_status=Rejected&notes=${encodeURIComponent(fullNotes)}`  })  .then(response => response.json())  .then(data => {  if (data.success) {  alert('Job order rejected and returned to staff.');  closeModal('reviewModal');  location.reload();  } else {  alert('Error: ' + data.message);  }  });
}  function viewJobDetails(jobId) {  window.open(`job_order_detail.php?id=${jobId}`, '_blank');
}  function closeModal(modalId) {  document.getElementById(modalId).style.display = 'none';
}  // Close modal when clicking outside
window.onclick = function(event) {  if (event.target.classList.contains('modal')) {  event.target.style.display = 'none';  }
}
</script>  <?php include __DIR__ . '/../partials/footer.php'; ?>
